/* ===================================================================== LAYOUT
 * A run is laid out left→right as a sequence of nodes:
 *   {k:'post', role:'end'|'line'|'corner'|'gate'|'guide'|'pier', w}
 *   {k:'bay', w}   clear width between posts
 *   {k:'gate', w, slideDir}   clear opening between gate posts
 * Run length is measured outside-of-post to outside-of-post.
 * ------------------------------------------------------------------------- */
function gateLeaves(g, rules){
  const G = g.width;
  if (g.type === 'double')     return {n:2, w:(G - 3*rules.hingeGap)/2};
  if (g.type === 'sliding')    return {n:1, w:G + rules.slidingOverlap};
  if (g.type === 'cantilever') return {n:1, w:G*1.5};                       // 50% counterbalance tail — RJL default
  if (g.type === 'bifold')     return {n:4, w:(G - 3*rules.hingeGap)/4};    // 2 leaves × 2 folding panels
  if (g.type === 'boom')       return {n:0, w:G + 300};                     // boom arm = opening + 300 mm
  if (g.type === 'bollards')   return {n:0, w:0};
  return {n:1, w:G - 2*rules.hingeGap};
}
const SLIDES = t => t === 'sliding' || t === 'cantilever';
function gatePostW(run, rules){
  const g = run.gate, P = PRODUCTS[run.product]; if (g.type === 'none') return 0;
  if (g.type === 'boom') return 350;                    // barrier cabinet footprint
  if (g.type === 'bollards') return P.noPosts ? P.postW : (P.postW || 50);   // lane ends on ordinary fence posts
  if (P.noPosts) return P.postW;                        // glass hangs off glass panels; temp gates clamp to panels
  if (g.piers) return 350;
  if (g.type === 'bifold') return 150;
  if (g.type === 'pedestrian') return P.pool ? 50 : 65;
  if (SLIDES(g.type) || isAuto(g) || gateLeaves(g, rules).w > rules.heavyLeafWidth) return 100;
  return 65;
}
/* Split a clear length into bays.
 *  'full'  — as many full-width bays as fit, then one cut-down bay (sheet & panel systems; matches retail Colorbond output)
 *  'equal' — equal bays no wider than max (slat systems; matches retail aluminium slat output) */
function splitBays(clear, p, W, strategy){
  if (clear <= 0.5) return [];
  if (strategy === 'full'){
    const k = Math.floor((clear + p)/(W + p) + 1e-9);
    if (k === 0) return [clear];
    const rem = clear - k*W - (k-1)*p;            // space left after k full bays and k-1 posts
    if (rem < 1) return Array(k).fill(W);
    const r = rem - p;                             // trailing bay after one more post
    if (r >= 300) return [...Array(k).fill(W), r];
    const two = (W + rem - p)/2;                   // trailing bay too short: share across last two bays
    return [...Array(k-1).fill(W), two, two];
  }
  const n = Math.max(1, Math.ceil((clear + p)/(W + p) - 1e-9));
  return Array(n).fill((clear - (n-1)*p)/n);
}
function layoutRun(run, rules){
  const P = PRODUCTS[run.product], p = P.postW;
  const W = clamp(run.maxBay, 300, P.maxBayLimit);
  const L = Math.round(run.length*1000), g = run.gate, errs = [], seq = [];
  const post = (role, w) => seq.push({k:'post', role, w});
  const bays = clear => splitBays(clear, p, W, P.strategy).forEach((b,i) => { if (i) post('line', p); seq.push({k:'bay', w:b}); });
  let gw = 0;
  if (g.type === 'none'){
    if (L < 2*p + 300) errs.push(`Run is too short. It needs at least ${fmt(2*p+300)} mm.`);
    else { post('end', p); bays(L - 2*p); post('end', p); }
  } else {
    gw = gatePostW(run, rules);
    const G = g.width, block = 2*gw + G, sliding = SLIDES(g.type);
    const roleL = d => g.piers ? 'pier' : (sliding && d < 0 ? 'guide' : 'gate');
    const roleR = d => g.piers ? 'pier' : (sliding && d > 0 ? 'guide' : 'gate');
    const gateBlock = d => { post(roleL(d), gw); seq.push({k:'gate', w:G, slideDir:d}); post(roleR(d), gw); };
    const fenceLen = L - block;
    if (fenceLen < -0.5){
      errs.push(`The gate and its posts need ${fmt(block)} mm but the run is ${fmt(L)} mm. Lengthen the run or narrow the gate.`);
    } else if (g.position === 'middle'){
      const side = fenceLen/2;
      if (side < p + 300) errs.push(`Each side of the gate is only ${fmt(side)} mm. Put the gate at the start or end, or lengthen the run.`);
      else { post('end', p); bays(side - p); gateBlock(1); bays(side - p); post('end', p); }
    } else {
      const atStart = g.position === 'start';
      if (fenceLen < 1){ gateBlock(atStart ? 1 : -1); }
      else if (fenceLen < p + 300) errs.push(`The fence beside the gate is only ${fmt(fenceLen)} mm. Make the run ${fmt(block)} mm (gate only) or at least ${fmt(block+p+300)} mm.`);
      else if (atStart){ gateBlock(1); bays(fenceLen - p); post('end', p); }
      else { post('end', p); bays(fenceLen - p); gateBlock(-1); }
    }
  }
  let x = 0; seq.forEach(n => { n.x = x; x += n.w; });
  return { L, W, p, gw, seq, errs };
}
function sections(seq){
  const out = []; let cur = null;
  for (const n of seq){
    if (n.k === 'bay'){ if (!cur){ cur = {len:0, bays:0}; out.push(cur); } cur.len += n.w; cur.bays++; }
    else if (n.k === 'post' && n.role === 'line' && cur) cur.len += n.w;
    else cur = null;
  }
  return out;
}

/* ===================================================================== BOM */
function cutPlan(lens, stock, kerf){
  const sorted = [...lens].sort((a,b) => b-a), bins = []; let over = 0, used = 0;
  for (const l of sorted){
    if (l > stock){ over++; continue; }
    used += l;
    const b = bins.find(b => b.rem >= l + (b.n ? kerf : 0));
    if (b){ b.rem -= l + (b.n ? kerf : 0); b.n++; } else bins.push({rem:stock - l, n:1});
  }
  const waste = bins.length ? (bins.length*stock - used)/(bins.length*stock)*100 : 0;
  return { bins:bins.length, over, waste };
}
function naiveLengths(lens, stock, kerf){            // retail method: pack each length size separately
  const m = new Map(); lens.forEach(l => m.set(l, (m.get(l)||0) + 1));
  let n = 0; for (const [l,c] of m){ if (l > stock) continue; n += Math.ceil(c / Math.max(1, Math.floor((stock + kerf)/(l + kerf)))); }
  return n;
}
class Bom {
  constructor(){ this.lines = new Map(); this.pieces = new Map(); this.warn = []; }
  add(cat, code, desc, qty, unit='ea', basis=''){
    if (!(qty > 0)) return;
    const l = this.lines.get(code);
    if (l){ l.qty += qty; if (basis && !l.basis.includes(basis)) l.basis = l.basis ? l.basis + '; ' + basis : basis; }
    else this.lines.set(code, {cat, code, desc, qty, unit, basis});
  }
  piece(cat, code, desc, stock, len, count=1, basis=''){
    if (!(count > 0)) return;
    let p = this.pieces.get(code);
    if (!p){ p = {cat, code, desc, stock, lens:[], basis}; this.pieces.set(code, p); }
    for (let i=0;i<count;i++) p.lens.push(Math.round(len));
  }
  finish(kerf){
    for (const p of this.pieces.values()){
      const plan = cutPlan(p.lens, p.stock, kerf), naive = naiveLengths(p.lens, p.stock, kerf);
      let basis = `${p.lens.length} cuts, ${plan.waste.toFixed(1)}% offcut`;
      if (naive > plan.bins) basis += `; saves ${naive - plan.bins} length${naive-plan.bins>1?'s':''} vs cutting each size separately`;
      if (p.basis) basis = p.basis + '. ' + basis;
      this.add(p.cat, p.code, `${p.desc}, ${(p.stock/1000).toFixed(1)} m lengths`, plan.bins, 'len', basis);
      if (plan.over) this.warn.push(`${p.desc}: ${plan.over} piece(s) are longer than the ${p.stock} mm stock length and are not counted. Check the height or post depth.`);
    }
    this.list = [...this.lines.values()].map(l => {
      let q = l.qty;
      if (l.cat === 'Labour') q = Math.round(q*10)/10;
      else if (INT_UNITS.has(l.unit)) q = Math.ceil(q - 1e-9);
      else q = Math.ceil(q*10 - 1e-9)/10;
      return {...l, qty:q};
    }).sort((a,b) => CATS.indexOf(a.cat) - CATS.indexOf(b.cat));
  }
}

function fixings(c, count, w, bagsEach, basis){
  if (!count) return;
  if (c.ground) c.bom.add('Concrete & footings','CONC-20','Concrete post mix, 20 kg bag', count*bagsEach, 'bag', basis || `${bagsEach} bags per post hole`);
  else { c.bom.add('Hardware',`BASEPLATE-${w}`,`Base plate to suit ${w} mm post`, count, 'ea', '1 per post');
         c.bom.add('Hardware','ANCHOR-M12','M12 chemical anchor', count*4, 'ea', '4 per base plate'); }
}

/* Colorbond top features. Lattice styles are generic trellis patterns; the lattice panel make-up follows Oxworks
 * (2400 × 1500 panel = 3 × 1190 sheets, 3 rails, 1 × 2390 laser-cut lattice infill, 22 tek screws) — FROM SOURCE. */
const LATTICE_STYLES = {square:'Square trellis', diamond:'Diamond trellis', hslat:'Horizontal slat trellis', vslat:'Vertical slat trellis', laser:'Laser-cut decorative'};
const CB_TOP = st => st === 'breezeway' || st === 'slatfx' || st === 'lattice';
function cbTopInfill(run, w, gate){
  if (run.style === 'breezeway') return [gate ? `CB-GBWAY-${w}` : 'CB-BWAY-2390', gate ? `Breezeway gate infill, ${w} × 250` : 'Breezeway infill, 2390 × 250'];
  if (run.style === 'slatfx')    return [gate ? `CB-GSLAT-${w}` : 'CB-SLATFX-2390', gate ? `Slat FX gate infill, ${w} × 250` : 'Slat FX infill, 2390 × 250'];
  const k = run.lattice || 'square', n = LATTICE_STYLES[k] || 'Lattice';
  return [gate ? `CB-GLAT-${k}-${w}` : `CB-LAT-${k}-2390`, gate ? `${n} gate lattice infill, ${w} × 310` : `${n} lattice infill, 2390 × 310`];
}
/* Timber paling build-up (RJL spec, Oct 2026):
 *   palings 1650 mm (5'4") or 1950 mm (6'4"); capping adds 250 mm (1650 palings + capping = 1900 mm);
 *   a second plinth board adds 150 mm; each 200 × 50 treated pine sleeper adds 200 mm (1 or 2 sleepers);
 *   with 2 sleepers RJL recommends 100 × 100 SHS steel posts instead of timber.
 *   Construction per RJL detail: lapped = "under" palings with a 50-70 mm gap, "over" palings covering each gap. */
const PAL_CAP = 250, PAL_PLINTH = 150, PAL_SLEEPER = 200;
function palingHeight(r){ return (+r.palingLen || 1650) + (r.capping ? PAL_CAP : 0) + ((r.plinths|0) > 1 ? PAL_PLINTH : 0) + (r.sleepers|0)*PAL_SLEEPER; }
const palingSteel = r => r.product === 'paling' && (r.sleepers|0) >= 2;
/* Retaining wall under the fence: concrete sleepers (200 mm high) between 150 UC "H-beam" uprights. */
const RET_SLEEPER_H = 200;
const retainOn = r => !!(r.retain && r.retain.on) && !PRODUCTS[r.product].noPosts;
const retainH = r => retainOn(r) ? Math.max(RET_SLEEPER_H, Math.round((+r.retain.height || 0)/RET_SLEEPER_H)*RET_SLEEPER_H) : 0;
const BLADE_PITCH = {'45':60, '60':50, '90':100};   // blade centres by angle — RJL default
const PRODUCT_BOM = {
  colorbond(c){
    const {run,H,bom,postLen,fencePosts,bays} = c;
    const bw = CB_TOP(run.style), rows = bw ? 3 : 2, sheetH = H - (bw ? 310 : 10);
    const ends = fencePosts.filter(p => p.role !== 'line').length, lines = fencePosts.length - ends;
    const cut = bays.filter(b => b < 2390).length;
    bom.add('Posts',`SHS50-${postLen}`,`50×50 SHS steel post, ${postLen} mm`, ends, 'ea', 'End and corner posts');
    bom.add('Posts',`CB-CHPOST-${postLen}`,`Steel channel post, ${postLen} mm`, lines, 'ea', 'Line posts');
    bom.add('Hardware','CAP-SHS50','50×50 post cap', ends, 'ea', 'End and corner posts');
    bom.add('Hardware','CB-CHCAP','Channel post cap', lines, 'ea', 'Optional');
    bom.add('Panels & infill','CB-RAIL-2400','Panel rail, 2400 mm', rows*bays.length, 'ea', `${rows} per bay` + (cut ? `; ${cut} bay(s) cut down` : ''));
    bom.add('Panels & infill',`CB-SHEET-${sheetH}`,`Infill sheet, ${sheetH} mm`, bays.reduce((s,b) => s + Math.ceil(b/SHEET_COVER - 1e-9), 0), 'ea', `${SHEET_COVER} mm cover per sheet (estimate)`);
    if (bw){ const [code, desc] = cbTopInfill(run, 2390, false); bom.add('Panels & infill', code, desc, bays.length, 'ea', '1 per bay'); }
    if (run.style === 'lattice') bom.add('Hardware','TEK-10-16','10-16 × 16 tek screw', 22*bays.length, 'ea', '22 per lattice panel (Oxworks)');
    else bom.add('Hardware','TEK-10-16','10-16 × 16 tek screw', rows*bays.length*4, 'ea', '4 per rail (estimate)');
  },
  hslat(c){
    const {run,H,bom,postLen,fencePosts,bays} = c;
    const pitch = 65 + run.gap, n = Math.floor(H/pitch);
    const ends = fencePosts.filter(p => p.role === 'end').length;
    bom.piece('Posts','AL-CH1','50×50 1-way channel post', 5800, postLen, ends, 'End posts');
    bom.piece('Posts','AL-CH2','50×50 2-way channel post', 5800, postLen, fencePosts.length - ends, 'Line and corner posts');
    bays.forEach(b => bom.piece('Panels & infill','AL-SLAT65','65×16 slat', 5800, b, n, `${n} slats per bay at ${pitch} mm pitch`));
    bays.forEach(() => bom.piece('Panels & infill','AL-COVER','Snap-on channel cover', 5800, H, 2, '1 per channel face'));
    bom.add('Hardware','AL-CHCAP','Channel cap (plastic)', 2*bays.length, 'ea', '2 per bay');
    bom.add('Hardware','AL-PCAP','Post cap (plastic)', fencePosts.length, 'ea', '1 per post');
    bom.add('Hardware','TEK-COL','Coloured tek screw', 2*n*bays.length, 'ea', '2 per slat');
  },
  vslat(c){
    const {run,H,bom,postLen,fencePosts,bays} = c;
    const pitch = 65 + run.gap, rows = H > 1500 ? 3 : 2, pl = H - 75;
    let pk = 0;
    bom.piece('Posts','AL-SHS50','50×50 aluminium SHS post', 6500, postLen, fencePosts.length, '1 per post');
    bays.forEach(b => {
      const n = Math.floor((b + run.gap)/pitch); pk += n;
      bom.piece('Panels & infill','AL-RAIL5025','50×25 aluminium rail', 6500, b, rows, `${rows} rails per bay`);
      bom.piece('Panels & infill','AL-PICKET65','65×16 vertical slat', 6500, pl, n, `${pl} mm long at ${pitch} mm pitch`);
    });
    bom.add('Hardware','AL-RBRKT','Rail bracket', rows*2*bays.length, 'ea', '2 per rail');
    bom.add('Hardware','TEK-COL','Coloured tek screw', pk*rows + rows*4*bays.length, 'ea', '1 per slat per rail + 2 per bracket');
    bom.add('Hardware','CAP-SHS50','50×50 post cap', fencePosts.length, 'ea', '1 per post');
  },
  chain(c){
    const {run,H,bom,postLen,fencePosts,secs,rules,ground} = c;
    const R = run.rails || {top:true};
    const term = fencePosts.filter(p => p.role !== 'line').length, line = fencePosts.length - term;
    const total = secs.reduce((a,s) => a + s.len, 0), ends = 2*secs.length;
    const railLens = secs.reduce((a,s) => a + Math.ceil(s.len/6400), 0);
    const railRows = ['top','mid','bot'].filter(k => R[k]);
    const wireRows = ['top','mid','bot'].filter(k => !R[k]);               // a line wire wherever there is no rail
    bom.add('Posts',`PIPE50-${postLen}`,`50 NB galvanised pipe terminal post, ${postLen} mm`, term, 'ea', 'End and corner posts');
    bom.add('Posts',`PIPE40-${postLen}`,`40 NB galvanised pipe line post, ${postLen} mm`, line, 'ea', 'Line posts');
    bom.add('Posts','STAY40','40 NB stay (brace)', ends, 'ea', '1 at each end of each mesh section');
    const names = {top:'top', mid:'middle', bot:'bottom'};
    railRows.forEach(k => bom.add('Panels & infill','PIPE32-6500','32 NB rail, 6.5 m lengths', railLens, 'len', `${railRows.map(r => names[r]).join(', ')} rail(s); 100 mm overlap at joins`));
    if (railRows.length) bom.add('Hardware','RAIL-JOIN','Rail joiner sleeve', railRows.length*Math.max(0, railLens - secs.length), 'ea', '1 per rail join');
    if (R.top) bom.add('Hardware','CAP-40LOOP','40 NB loop cap (carries top rail)', line, 'ea', 'Line posts');
    else bom.add('Hardware','CAP-40NB','40 NB dome cap', line, 'ea', 'Line posts');
    const clampRows = railRows.filter(k => k !== 'top').length;
    if (clampRows) bom.add('Hardware','RAIL-CLAMP','Rail-to-post clamp (mid / bottom rail)', clampRows*line, 'ea', '1 per line post per rail');
    if (railRows.length) bom.add('Hardware','RAIL-END','Rail end cup with band', railRows.length*ends, 'ea', '1 per rail end at terminals');
    bom.add('Panels & infill',`CHAIN50-${H}`,`50 mm chainmesh, ${H} mm high, 15 m roll`, Math.ceil(total/15000 - 1e-9), 'roll', `${(total/1000).toFixed(1)} m of mesh`);
    if (wireRows.length){
      bom.add('Panels & infill','WIRE-LINE','Line wire', wireRows.length*total*1.1/1000, 'm', `${wireRows.length} strand(s) where there is no rail, + 10%`);
      bom.add('Hardware','STRAINER','Wire strainer', ends*wireRows.length, 'ea', '1 per line wire at each mesh end');
    }
    bom.add('Hardware','TIE-WIRE','Mesh tie', line*Math.ceil(H/300) + railRows.length*Math.ceil(total/450), 'ea', 'Every 300 mm on posts, 450 mm on rails');
    bom.add('Hardware',`TBAR-${H}`,`Tension bar, ${H} mm`, ends, 'ea', '1 at each mesh end');
    bom.add('Hardware','TBAND','Tension band', ends*Math.ceil(H/350), 'ea', 'Every 350 mm on tension bars');
    bom.add('Hardware','CAP-50NB','50 NB dome cap', term, 'ea', 'Terminal posts');
    if (ground) bom.add('Concrete & footings','CONC-20','Concrete post mix, 20 kg bag', term*2 + line*rules.bagsPerHole + ends, 'bag', `Terminals 2, line posts ${rules.bagsPerHole}, stays 1`);
    else fixings(c, fencePosts.length, 60, 0);
  },
  paling(c){
    const {run,H,bom,fencePosts,bays,P,rules,ground} = c;
    const lap = run.style !== 'butted', pw = +run.palingW || 150, gap = clamp(+run.gap || 60, 0, 100);
    const pl = +run.palingLen || 1650, rails = 3, steel = palingSteel(run), retained = retainOn(run);
    // posts: timber 125 × 75, or 100 × 100 SHS steel with 2 sleepers (RJL recommendation). On a retaining wall the
    // post bolts to the H-beam instead of going in the ground (fixings counted in retainBom).
    const postLen = retained ? H + 300 : c.postLen;
    if (steel) bom.add('Posts',`SHS100-${postLen}`,`100×100 SHS steel post, ${postLen} mm`, fencePosts.length, 'ea', 'Recommended with double sleepers');
    else bom.add('Posts',`PINE125-${postLen}`,`125×75 H4 treated pine post, ${postLen} mm`, fencePosts.length, 'ea', '1 per post');
    if (steel) bom.add('Hardware','CAP-SHS100','100×100 post cap', fencePosts.length, 'ea', '1 per post');
    if (steel) bom.add('Hardware','RAIL-BRKT-STEEL','Rail-to-steel-post bracket', fencePosts.length*rails*2, 'ea', '2 per rail per post');
    let pals = 0;
    bays.forEach(b => {
      const span = b + P.postW;                                   // rails, plinths and sleepers run post centre to post centre
      const n = lap ? 2*Math.ceil((span + gap)/(pw + gap) - 1e-9) - 1 : Math.ceil(span/pw - 1e-9);
      pals += n;
      bom.piece('Panels & infill','PINE-RAIL7538','75×38 H3 pine rail', 4800, span, rails, '3 rails per bay (top, middle, bottom)');
      bom.piece('Panels & infill','PINE-PLINTH','150×25 H4 plinth board', 4800, span, Math.max(1, run.plinths|0), `${Math.max(1, run.plinths|0)} per bay`);
      if (run.sleepers) bom.piece('Panels & infill','PINE-SLEEPER','200×50 H4 treated pine sleeper', 2400, span, run.sleepers|0, `${run.sleepers} per bay`);
      if (run.capping){ bom.piece('Panels & infill','PINE-CAP','140×19 capping board', 4800, span, 1, '1 per bay');
                        bom.piece('Panels & infill','PINE-TRIM','70×35 capping trim rail', 4800, span, 1, '1 per bay'); }
    });
    bom.add('Panels & infill',`PALING-${pw}-${pl}`,`${pw}×16 paling, ${pl} mm`, pals, 'ea',
      lap ? `Lapped: under palings at ${gap} mm gaps, over palings covering each gap` : `Butted: 1 per ${pw} mm`);
    bom.add('Hardware','NAIL-GALV','Galvanised nail (pack of 500)', pals*rails*2/500, 'pack', '2 per paling per rail');
    if (run.sleepers) bom.add('Hardware','SLEEPER-SCREW','Batten screw for sleepers', bays.length*(run.sleepers|0)*4, 'ea', '2 per sleeper end');
    if (!retained && !steel) { /* concrete counted by fixings() in runBom */ }
  },
  picket(c){
    const {run,H,bom,postLen,fencePosts,bays,P} = c;
    const pitch = 70 + run.gap, pl = H - 100; let n = 0;
    bom.add('Posts',`POST75-${postLen}`,`75×75 post, ${postLen} mm`, fencePosts.length, 'ea', '1 per post');
    bays.forEach(b => { const k = Math.floor((b + P.postW + run.gap)/pitch); n += k;
      bom.piece('Panels & infill','PICKET-RAIL','70×35 picket rail', 4800, b + P.postW, 2, '2 rails per bay'); });
    bom.add('Panels & infill',`PICKET-${pl}`,`70 mm picket, ${pl} mm`, n, 'ea', `${pitch} mm pitch`);
    bom.add('Hardware','NAIL-GALV','Galvanised nail (pack of 500)', n*4/500, 'pack', '2 per picket per rail');
    bom.add('Hardware','CAP-POST75','75×75 post cap', fencePosts.length, 'ea', '1 per post');
  },
  vblade(c){
    const {run,H,bom,postLen,fencePosts,bays} = c;
    const pitch = BLADE_PITCH[run.style] || 60, bl = H - 100; let n = 0;
    bom.piece('Posts','AL-SHS50','50×50 aluminium SHS post', 6500, postLen, fencePosts.length, '1 per post');
    bays.forEach(b => { const k = Math.floor(b/pitch); n += k;
      bom.piece('Panels & infill','AL-BLADERAIL','Blade carrier rail (top and bottom)', 6500, b, 2, '2 per bay'); });
    bom.piece('Panels & infill','AL-BLADE75','75 mm aluminium blade', 6500, bl, n, `${bl} mm long at ${pitch} mm pitch, angled ${run.style}°`);
    bom.add('Hardware','AL-BLADECLIP','Blade clip / end cap', 2*n, 'ea', '2 per blade');
    bom.add('Hardware','AL-RBRKT','Rail bracket', 4*bays.length, 'ea', '2 per rail');
    bom.add('Hardware','TEK-COL','Coloured tek screw', 2*n + 8*bays.length, 'ea', '1 per clip + 2 per bracket');
    bom.add('Hardware','CAP-SHS50','50×50 post cap', fencePosts.length, 'ea', '1 per post');
  },
  sbatten(c){
    const {run,H,bom,postLen,fencePosts,bays} = c;
    const bw = +run.style || 50, pitch = bw + run.gap, rows = H > 1500 ? 3 : 2, bl = H - 75; let n = 0;
    bom.piece('Posts','SHS50-ST','50×50 SHS steel post', 6500, postLen, fencePosts.length, '1 per post');
    bays.forEach(b => { const k = Math.floor((b + run.gap)/pitch); n += k;
      bom.piece('Panels & infill','RHS5025-ST','50×25 RHS steel rail', 6500, b, rows, `${rows} rails per bay`); });
    bom.piece('Panels & infill',`BATTEN${bw}-ST`,`${bw}×25 steel batten`, 6500, bl, n, `${bl} mm long at ${pitch} mm pitch`);
    bom.add('Hardware','TEK-COL','Coloured tek screw', n*rows, 'ea', '1 per batten per rail');
    bom.add('Hardware','ST-RBRKT','Rail bracket', rows*2*bays.length, 'ea', '2 per rail');
    bom.add('Hardware','CAP-SHS50','50×50 post cap', fencePosts.length, 'ea', '1 per post');
  },
  poolalu(c){
    const {run,H,bom,postLen,fencePosts,bays} = c;
    const W = Math.min(run.maxBay, 2450), cut = bays.filter(b => b < W - 5).length;
    bom.add('Posts',`AL-SHS50-${postLen}`,`50×50 aluminium post, ${postLen} mm`, fencePosts.length, 'ea', '1 per post');
    bom.add('Panels & infill',`POOL-AL-${H}`,`Pool-compliant aluminium flat-top panel, ${W} × ${H}`, bays.length, 'ea', (cut ? `${cut} panel(s) cut to suit; ` : '') + 'gaps ≤ 100 mm');
    bom.add('Hardware','AL-PBRKT','Panel bracket', 4*bays.length, 'ea', '4 per panel');
    bom.add('Hardware','TEK-COL','Coloured tek screw', 8*bays.length, 'ea', '2 per bracket');
    bom.add('Hardware','CAP-SHS50','50×50 post cap', fencePosts.length, 'ea', '1 per post');
  },
  glass(c){
    const {run,H,bom,bays,ground} = c;
    bays.forEach(b => { const w = Math.round(b/10)*10;
      bom.add('Panels & infill',`GLASS12-${w}x${H}`,`12 mm toughened glass panel, ${w} × ${H}`, 1, 'ea', 'Equal panels, 30 mm gaps'); });
    if (run.style === 'channel'){
      const len = bays.reduce((a,b) => a + b + 30, 0);
      bom.add('Hardware','GLASS-CHANNEL','Hidden base channel', len/1000, 'm', 'Full fence length');
      bom.add('Hardware','GLASS-WEDGE','Channel wedge gasket set', bays.length*2, 'set', '2 per panel');
    } else {
      bom.add('Hardware', ground ? 'SPIGOT-CORE' : 'SPIGOT-BASE', ground ? 'Core-drilled spigot' : 'Base-plate spigot', 2*bays.length, 'ea', '2 per panel');
      if (ground) bom.add('Concrete & footings','CORE-DRILL','Core drill and grout spigot hole', 2*bays.length, 'ea', '1 per spigot');
    }
  },
  mesh868(c){
    const {run,H,bom,postLen,fencePosts,bays} = c;
    const W = Math.min(run.maxBay, 2500), cut = bays.filter(b => b < W - 5).length;
    bom.add('Posts',`SHS60-${postLen}`,`60×60 SHS post, ${postLen} mm`, fencePosts.length, 'ea', '1 per post');
    bom.add('Panels & infill',`MESH868-${H}`,`Double wire mesh panel 8/6/8, ${W} × ${H}`, bays.length, 'ea', cut ? `${cut} panel(s) cut to suit` : '1 per bay');
    bom.add('Hardware','CLAMP868','Panel clamp with security bolt', fencePosts.length*(Math.ceil(H/600) + 1), 'ea', 'Every 600 mm per post');
    bom.add('Hardware','CAP-SHS60','60×60 post cap', fencePosts.length, 'ea', '1 per post');
  },
  palisade(c){
    const {H,bom,postLen,fencePosts,bays,P} = c;
    const rows = H > 2000 ? 3 : 2; let pales = 0;
    bom.add('Posts',`PAL-POST-${postLen}`,`100×55 palisade post, ${postLen} mm`, fencePosts.length, 'ea', '1 per post');
    bays.forEach(b => { const n = Math.floor((b + 70)/140); pales += n;
      bom.piece('Panels & infill','PAL-RAIL','50×50×6 angle rail', 6500, b + P.postW, rows, `${rows} rails per bay`); });
    bom.add('Panels & infill',`PAL-PALE-${H}`,`W-section pale, triple-point top, ${H} mm`, pales, 'ea', '140 mm centres');
    bom.add('Hardware','PAL-BOLT','Anti-tamper shear bolt', pales*rows, 'ea', '1 per pale per rail');
    bom.add('Hardware','PAL-FISH','Rail fishplate', rows*2*bays.length, 'ea', '2 per rail');
  },
  garrison(c){
    const {run,H,bom,postLen,fencePosts,bays} = c;
    const W = Math.min(run.maxBay, 2400), cut = bays.filter(b => b < W - 5).length;
    bom.add('Posts',`SHS65-${postLen}`,`65×65 SHS post, ${postLen} mm`, fencePosts.length, 'ea', '1 per post');
    bom.add('Panels & infill',`GARR-${H}`,`Garrison spear-top security panel, ${W} × ${H}`, bays.length, 'ea', cut ? `${cut} panel(s) cut to suit` : '1 per bay');
    bom.add('Hardware','GARR-BRKT','Security panel bracket', 6*bays.length, 'ea', '6 per panel (3 rails)');
    bom.add('Hardware','SECBOLT','Security bolt', 6*bays.length, 'ea', '1 per bracket');
    bom.add('Hardware','CAP-SHS65','65×65 post cap', fencePosts.length, 'ea', '1 per post');
  },
  temp(c){
    const {bom,bays,secs} = c;
    const feet = bays.length + secs.length, stays = Math.ceil(bays.length/4);
    bom.add('Panels & infill','TEMP-PANEL','Temporary fence panel, 2400 × 2100', bays.length, 'ea', '1 per bay');
    bom.add('Hardware','TEMP-FOOT','Temporary fence foot (block)', feet + stays, 'ea', '1 per panel join + 1 per stay');
    bom.add('Hardware','TEMP-CLAMP','Panel coupler clamp', Math.max(0, bays.length - secs.length), 'ea', '1 per panel join');
    bom.add('Hardware','TEMP-STAY','Bracing stay', stays, 'ea', '1 per 4 panels');
    bom.add('Hardware','SANDBAG','Sandbag', stays*2, 'ea', '2 per stay');
  },
  mesh358(c){
    const {run,H,bom,postLen,fencePosts,bays} = c;
    const W = Math.min(run.maxBay, 2500), cut = bays.filter(b => b < W - 5).length;
    bom.add('Posts',`SHS60-${postLen}`,`60×60 SHS post, ${postLen} mm`, fencePosts.length, 'ea', '1 per post');
    bom.add('Panels & infill',`MESH358-${H}`,`358 welded mesh panel, ${W} × ${H}`, bays.length, 'ea', cut ? `${cut} panel(s) cut to suit` : '1 per bay');
    bom.add('Hardware',`CLAMP358-${H}`,`Clamp bar, ${H} mm`, fencePosts.length, 'ea', '1 per post');
    bom.add('Hardware','SECBOLT','Security bolt', fencePosts.length*Math.ceil(H/250), 'ea', 'Every 250 mm on clamp bars');
    bom.add('Hardware','CAP-SHS60','60×60 post cap', fencePosts.length, 'ea', '1 per post');
  },
  tubular(c){
    const {run,H,bom,postLen,fencePosts,bays} = c;
    const W = Math.min(run.maxBay, 2450), cut = bays.filter(b => b < W - 5).length;
    bom.add('Posts',`SHS50-${postLen}`,`50×50 SHS steel post, ${postLen} mm`, fencePosts.length, 'ea', '1 per post');
    bom.add('Panels & infill',`TUB-${H}`,`Tubular steel panel, ${W} × ${H}`, bays.length, 'ea', cut ? `${cut} panel(s) cut to suit` : '1 per bay');
    bom.add('Hardware','TUB-BRKT','Panel bracket', 4*bays.length, 'ea', '4 per panel');
    bom.add('Hardware','TEK-10-16','10-16 × 16 tek screw', 8*bays.length, 'ea', '2 per bracket');
    bom.add('Hardware','CAP-SHS50','50×50 post cap', fencePosts.length, 'ea', '1 per post');
  }
};

/* Security add-ons for commercial systems: barbed wire, razor coil (on arms or in line on post tops), electric fence.
 * Electric fence totals are collected per job in ELEC so energisers, keypad, earths and signs are counted once. */
let ELEC = {len:0};
function toppingBom(c){
  const {run,bom,fencePosts,bays,secs} = c;
  const total = secs.reduce((a,s) => a + s.len, 0), ends = 2*secs.length, posts = fencePosts.length;
  if (!total) return;
  if (run.barbed || run.razor){
    const inline = run.razor && run.razorMount === 'inline';
    if (inline) bom.add('Hardware','POST-EXT-450','In-line razor post extension, 450 mm', posts, 'ea', '1 per post; coil sits on top of the fence line');
    else bom.add('Hardware', run.razor ? 'ARM-Y' : 'ARM-45', run.razor ? 'Y-arm (razor coil + barbed strands)' : '45° extension arm (3-strand)', posts, 'ea', '1 per post');
    const strands = run.barbed ? 3 : (inline ? 1 : 2);
    bom.add('Panels & infill','WIRE-BARB','Barbed wire', strands*total*1.05/1000, 'm', run.barbed ? '3 strands + 5%' : `${strands} coil support strand${strands > 1 ? 's' : ''} + 5%`);
    bom.add('Hardware','STRAINER','Wire strainer', ends*strands, 'ea', '1 per barbed strand at each section end');
    if (run.razor){
      bom.add('Panels & infill','RAZOR-450','Razor wire coil, 450 mm', total*1.05/1000, 'm', 'Fence length + 5%');
      bom.add('Hardware','RAZOR-CLIP','Razor coil clip', Math.ceil(total/300), 'ea', 'Every 300 mm to support strands');
    }
  }
  if (run.electric){
    const k = clamp(run.elecStrands|0, 2, 30), top = run.elecMount === 'top';
    const inter = bays.reduce((a,b) => a + Math.max(0, Math.ceil(b/3000 - 1e-9) - 1), 0);   // extra brackets on bays over 3 m
    bom.add('Hardware', top ? 'EF-BRKT-TOP' : 'EF-BRKT-FACE', top ? 'Electric fence top bracket (outrigger)' : 'Electric fence face-mount bracket (Y-standard)', posts + inter, 'ea', '1 per post + 1 per 3 m on long bays');
    bom.add('Hardware','EF-INSUL','Electric fence insulator', (posts + inter)*k, 'ea', `${k} per bracket`);
    bom.add('Panels & infill','EF-WIRE','Electric fence wire', k*total*1.05/1000, 'm', `${k} strands + 5%`);
    bom.add('Hardware','EF-TENS','Electric fence wire tensioner', k*ends, 'ea', '1 per strand at each section end');
    bom.add('Hardware','EF-CLAMP','Line clamp / jumper', 2*secs.length*2, 'ea', 'Live and earth jumpers at each section end');
    ELEC.len += total/1000;
  }
}
function electricJobBom(bom, rules){
  if (!ELEC.len) return;
  const z = Math.ceil(ELEC.len/rules.elecZoneLen - 1e-9);
  bom.add('Automation & access','EF-ENERGISER','JVA Z Range security energiser', z, 'ea', `1 per ${rules.elecZoneLen} m zone (e.g. Z14R: single zone, 4 J, networkable)`);
  bom.add('Automation & access','EF-KEYPAD','JVA Z Range LCD keypad', 1, 'ea', 'Arm / disarm and programming');
  bom.add('Automation & access','EF-BATT','12 V 7.2 Ah backup battery', z, 'ea', '1 per energiser');
  bom.add('Automation & access','EF-SIREN','Siren and strobe', 1, 'set', 'Driven from energiser outputs');
  bom.add('Automation & access','EF-ENCL','Energiser enclosure', z, 'ea', '1 per energiser');
  bom.add('Automation & access','EF-CUTOUT','Cut-out switch', z, 'ea', '1 per zone');
  bom.add('Automation & access','EF-LIGHTNING','Lightning diverter', z, 'ea', '1 per zone');
  bom.add('Hardware','EF-EARTH','Earth spike', 3*z, 'ea', '3 per energiser (confirm to manufacturer)');
  bom.add('Hardware','EF-HTCABLE','HT lead-out cable', 20*z, 'm', '20 m per energiser (estimate)');
  bom.add('Hardware','EF-SIGN','Electric fence warning sign', Math.ceil(ELEC.len/rules.signSpacing - 1e-9), 'ea', `Every ${rules.signSpacing} m`);
  bom.add('Labour','LAB-ELEC','Install electric fence', ELEC.len, 'm', 'All electrified fence');
  bom.add('Labour','LAB-ELEC-COMM','Commission and test energiser zone', z, 'ea', '1 per zone');
}
/* Retaining wall under the fence: 150 UC uprights at every fence post, concrete sleepers between them. */
function retainBom(c){
  const {run,bom,fencePosts,bays,rules} = c, wh = retainH(run), rows = wh/RET_SLEEPER_H;
  const embed = Math.max(rules.retainEmbedMin, wh);                 // RJL default: embed at least equal to retained height
  const beamLen = wh + embed;
  bom.add('Posts',`UC150-${beamLen}`,`150 UC steel upright (H-beam), ${beamLen} mm, galvanised`, fencePosts.length, 'ea', `Retained ${wh} mm + ${embed} mm in the ground`);
  bays.forEach(b => { const L = b + 150 <= 2000 ? 2000 : 2400;
    bom.add('Panels & infill',`CSLEEPER-${L}`,`Concrete sleeper ${L} × 200 × 80`, rows, 'ea', `${rows} per bay`); });
  bom.add('Concrete & footings','CONC-20','Concrete post mix, 20 kg bag', fencePosts.length*rules.bagsPerBeam, 'bag', `H-beams ${rules.bagsPerBeam} bags each`);
  bom.add('Hardware','FENCE-TO-UC','Fence post to H-beam bolt set (M12)', fencePosts.length, 'set', 'Fence post bolted to the top of each upright');
  const len = bays.reduce((a,b) => a + b, 0) + fencePosts.reduce((a,p) => a + p.w, 0);
  bom.add('Concrete & footings','AG-PIPE','100 mm slotted ag pipe with sock', len/1000, 'm', 'Drainage behind the wall');
  bom.add('Concrete & footings','DRAIN-GRAVEL','20 mm drainage gravel', Math.ceil(len/1000*wh/1000*0.3*10)/10, 'm³', '300 mm wide behind the wall');
  bom.add('Concrete & footings','GEOFABRIC','Geotextile fabric', Math.ceil(len/1000*(wh/1000 + 0.3)), 'm²', 'Behind sleepers');
  bom.add('Labour','LAB-RETAIN','Build sleeper retaining wall', len/1000*wh/1000, 'm²', 'Wall face area');
}
function runBom(run, lay, join, bom, rules){
  const P = PRODUCTS[run.product], H = run.height, ground = run.fixing === 'inground';
  const postLen = H + (ground ? rules.postEmbed : 0);
  const fencePosts = [];
  lay.seq.forEach((n,i) => {
    if (n.k !== 'post') return;
    if ((i === 0 && join.skipFirst) || (i === lay.seq.length-1 && join.skipLast)) return;
    if (n.role === 'end' || n.role === 'line' || n.role === 'corner') fencePosts.push(n);
  });
  const bays = lay.seq.filter(n => n.k === 'bay').map(n => n.w);
  const c = {run, P, H, ground, postLen, fencePosts, bays, secs:sections(lay.seq), bom, rules};
  if (bays.length) PRODUCT_BOM[run.product](c);
  if (run.product !== 'chain' && !P.noPosts && !retainOn(run)) fixings(c, fencePosts.length, palingSteel(run) ? 100 : P.postW, rules.bagsPerHole);
  if (retainOn(run) && bays.length) retainBom(c);
  if (P.topping && bays.length) toppingBom(c);
  const fenceMM = bays.reduce((a,b) => a+b, 0) + fencePosts.reduce((a,p) => a+p.w, 0);
  bom.add('Labour',`LAB-FENCE-${run.product}`,`Install ${P.label} fence`, fenceMM/1000, 'm', 'Fence length, gate openings excluded');
}

function gateBom(run, lay, bom, rules){
  const g = run.gate; if (g.type === 'none' || lay.errs.length) return;
  const P = PRODUCTS[run.product], H = run.height, lv = gateLeaves(g, rules), gw = lay.gw, n = lv.n, ground = run.fixing === 'inground';
  const leafW = Math.round(lv.w), leafH = SLIDES(g.type) ? H - 100 : H - 50;
  const TYPE = GATE_TYPES[g.type].label, auto = isAuto(g);
  const BEAMS = q => bom.add('Automation & access','BEAMS','Photo-electric safety beams (pair)', q, 'pair', 'Final count to site risk assessment');

  // ---- automated rising bollards
  if (g.type === 'bollards'){
    const nb = bollardCount(g.width), bh = +g.bollardH || 800, pl = H + (ground ? rules.postEmbed : 0);
    bom.add('Posts',`SHS${gw}-${pl}`,`${gw}×${gw} SHS end post, ${pl} mm`, 2, 'ea', 'Fence ends either side of the bollard lane');
    bom.add('Automation & access',`BOLLARD-AUTO-${bh}`,`Automated rising bollard, ${BOLLARD_D} mm dia × ${bh} mm rise, LED crown`, nb, 'ea',
      `${nb} at ≤ ${BOLLARD_CC} mm centres; LED crown green when fully down, red rising and up`);
    bom.add('Automation & access','BOLLARD-CTRL','Bollard control panel and power unit', 1, 'ea', 'Runs all bollards in the lane');
    bom.add('Automation & access','LOOP-DET','Vehicle loop detector', 1, 'ea', 'Safety and auto-raise');
    bom.add('Automation & access','LOOP','Inductive vehicle loop (cut in)', 2, 'ea', 'Safety loop + exit loop');
    bom.add('Concrete & footings','BOLLARD-FOOT','Bollard footing and sleeve, with drainage soak pit', nb, 'ea', '1 per bollard');
    bom.add('Concrete & footings','DUCT-50','50 mm conduit, control panel to bollards', Math.ceil(g.width/1000 + 6), 'm', 'Opening + 6 m to panel');
    if (g.access !== 'none') bom.add('Automation & access', ACCESS[g.access].code, ACCESS[g.access].label, 1, 'ea');
    laneAccessories(run, g, bom, true);
    bom.add('Labour','LAB-BOLLARD','Install and commission rising bollard', nb, 'ea');
    return;
  }
  // ---- boom gate: self-contained barrier, no leaves or gate posts
  if (g.type === 'boom'){
    bom.add('Automation & access','BOOM-BIONIK6','Bionik-6 boom barrier (brushless 36 V, 100% duty cycle)', 1, 'ea', 'RJL standard boom operator');
    bom.add('Automation & access',`BOOM-ARM-${leafW}`,`Boom arm, ${leafW} mm`, 1, 'ea', 'Opening + 300 mm');
    bom.add('Automation & access','BOOM-LIGHTS','Red / green flashing boom-arm lights', 1, 'set', 'RJL standard on all boom gates');
    bom.add('Automation & access','BOOM-REST','Fixed boom rest', 1, 'ea');
    bom.add('Automation & access','LOOP-DET','Vehicle loop detector', 1, 'ea', 'Safety and auto-close');
    bom.add('Automation & access','LOOP','Inductive vehicle loop (cut in)', 2, 'ea', 'Safety loop + exit loop');
    bom.add('Concrete & footings','BOOM-PAD','Boom barrier concrete pad', 1, 'ea', 'Size to manufacturer template');
    if (g.access !== 'none') bom.add('Automation & access', ACCESS[g.access].code, ACCESS[g.access].label, 1, 'ea');
    laneAccessories(run, g, bom, true);
    bom.add('Labour','LAB-AUTO','Install and commission gate automation', 1, 'ea');
    bom.add('Labour','LAB-GATE-boom','Install boom gate', 1, 'ea');
    return;
  }

  // ---- gate posts / piers
  if (P.noPosts){ /* glass gate hangs off the next glass panel; temp gate clamps to panels */ }
  else if (g.piers){
    bom.add('Gates',`PIER-${H+200}`,`Brick pier 350 × 350 × ${H+200} mm, with cap`, 2, 'ea', 'Either side of the opening');
    bom.add('Concrete & footings','PIER-FOOT','Pier footing, 600 × 600 × 600', 2, 'ea', '1 per pier');
    bom.add('Labour','LAB-PIER','Build brick pier', 2, 'ea');
  } else {
    const pl = H + (ground ? rules.gatePostEmbed : 0);
    bom.add('Posts',`SHS${gw}-${pl}`,`${gw}×${gw} SHS gate post, ${pl} mm`, 2, 'ea', SLIDES(g.type) ? 'Catch and guide posts' : 'Hinge and latch posts');
    bom.add('Hardware',`CAP-SHS${gw}`,`${gw}×${gw} post cap`, 2, 'ea', 'Gate posts');
    if (ground) bom.add('Concrete & footings','CONC-20','Concrete post mix, 20 kg bag', 2*rules.bagsPerGateHole, 'bag', `gate posts ${rules.bagsPerGateHole} bags each`);
    else { bom.add('Hardware',`BASEPLATE-${gw}`,`Base plate to suit ${gw} mm post`, 2, 'ea', '1 per post'); bom.add('Hardware','ANCHOR-M12','M12 chemical anchor', 8, 'ea', '4 per base plate'); }
  }

  // ---- leaves: prefabricated, or steel-framed with product infill
  const iw = leafW - 100, ih = leafH - 100;
  if (run.product === 'colorbond'){
    const bw = CB_TOP(run.style), rows = bw ? 3 : 2, sheetH = leafH - (bw ? 310 : 10);
    bom.add('Gates',`CB-GRAIL-${leafW}`,`Gate rail, ${leafW} mm`, rows*n, 'ea', `${rows} per leaf`);
    bom.add('Gates',`CB-STILE-${leafH}`,`Gate stile, ${leafH} mm`, 2*n, 'ea', '2 per leaf');
    bom.add('Gates',`CB-SHEET-${sheetH}`,`Infill sheet, ${sheetH} mm`, n*Math.ceil(leafW/SHEET_COVER - 1e-9), 'ea', 'Gate infill');
    if (bw){ const [code, desc] = cbTopInfill(run, leafW, true); bom.add('Gates', code, desc, n, 'ea', '1 per leaf'); }
    bom.add('Hardware','CAP-SHS50','50×50 post cap', 2*n, 'ea', 'Gate stiles');
    bom.add('Hardware','TEK-10-16','10-16 × 16 tek screw', 8*n, 'ea', '8 per leaf (estimate)');
  } else if (run.product === 'poolalu'){
    bom.add('Gates',`POOL-GATE-${leafW}x${leafH}`,`Pool-compliant aluminium gate, ${leafW} × ${leafH}`, n, 'ea', 'Prefabricated');
  } else if (run.product === 'glass'){
    bom.add('Gates',`GLASS-GATE-${leafW}x${leafH}`,`12 mm toughened glass gate, ${leafW} × ${leafH}`, n, 'ea', 'Hangs off the adjacent glass panel');
  } else if (run.product === 'temp'){
    bom.add('Gates','TEMP-GATE','Temporary fence gate panel', n, 'ea', '1 per leaf');
    bom.add('Hardware','TEMP-FOOT','Temporary fence foot (block)', n + 1, 'ea', 'Gate feet');
  } else {
    for (let i=0;i<n;i++){
      bom.piece('Gates','GATE-SHS50','50×50 SHS gate frame', 6500, leafW, 2, 'Leaf perimeter, plus mid rail on leaves over 1500 mm high');
      bom.piece('Gates','GATE-SHS50','', 6500, leafH, 2);
      if (leafH > 1500) bom.piece('Gates','GATE-SHS50','', 6500, iw, 1);
    }
    switch (run.product){
      case 'hslat': { const pitch = 65 + run.gap, k = Math.floor(ih/pitch);
        bom.piece('Panels & infill','AL-SLAT65','65×16 slat', 5800, iw, k*n); bom.add('Hardware','TEK-COL','Coloured tek screw', 2*k*n, 'ea', '2 per slat'); break; }
      case 'vslat': { const pitch = 65 + run.gap, k = Math.floor((iw + run.gap)/pitch);
        bom.piece('Panels & infill','AL-PICKET65','65×16 vertical slat', 6500, ih, k*n); bom.add('Hardware','TEK-COL','Coloured tek screw', 2*k*n, 'ea', '2 per gate slat'); break; }
      case 'paling': { const pw = +run.palingW || 150, gap = +run.gap || 60, lap = run.style !== 'butted';
        const k = lap ? 2*Math.ceil((iw + gap)/(pw + gap) - 1e-9) - 1 : Math.ceil(iw/pw - 1e-9);
        bom.add('Gates',`PALING-${pw}-${ih}`,`${pw}×16 paling, ${ih} mm (gate)`, k*n, 'ea', 'Fixed to steel gate frame'); break; }
      case 'picket': { const k = Math.floor((iw + run.gap)/(70 + run.gap));
        bom.add('Gates',`PICKET-${ih}`,`70 mm picket, ${ih} mm (gate)`, k*n, 'ea', 'Fixed to steel gate frame'); break; }
      case 'vblade': { const pitch = BLADE_PITCH[run.style] || 60, k = Math.floor(iw/pitch);
        bom.piece('Panels & infill','AL-BLADE75','75 mm aluminium blade', 6500, ih, k*n); bom.add('Hardware','AL-BLADECLIP','Blade clip / end cap', 2*k*n, 'ea', '2 per blade'); break; }
      case 'sbatten': { const bw = +run.style || 50, k = Math.floor((iw + run.gap)/(bw + run.gap));
        bom.piece('Panels & infill',`BATTEN${bw}-ST`,`${bw}×25 steel batten`, 6500, ih, k*n); bom.add('Hardware','TEK-COL','Coloured tek screw', 2*k*n, 'ea', '2 per gate batten'); break; }
      case 'chain': bom.add('Gates','CHAIN-GATE','Chainmesh for gate infill', n*iw*ih/1e6, 'm²', 'Cut from roll'); break;
      case 'mesh358': bom.add('Gates','MESH358-GATE','358 mesh panel cut to gate leaf', n*Math.ceil(iw/2500 - 1e-9), 'ea', 'Cut to suit'); break;
      case 'mesh868': bom.add('Gates','MESH868-GATE','Double wire mesh panel cut to gate leaf', n*Math.ceil(iw/2500 - 1e-9), 'ea', 'Cut to suit'); break;
      case 'palisade': bom.add('Gates',`PAL-PALE-${H}`,`W-section pale, triple-point top, ${H} mm`, n*Math.floor((iw + 70)/140), 'ea', 'Gate pales at 140 mm centres'); break;
      case 'tubular': case 'garrison': { const k = Math.floor(iw/(run.product === 'garrison' ? 125 : 100));
        bom.piece('Gates','SHS25-PICKET','25×25 SHS picket', 6500, ih + (run.product === 'garrison' ? 150 : 0), k*n, 'Gate pickets'); break; }
    }
  }

  // ---- hardware
  if (P.pool){
    bom.add('Hardware','HINGE-POOL', run.product === 'glass' ? 'Self-closing glass-to-glass hinge pair' : 'Self-closing pool gate hinge pair', 1, 'set', 'Gate must self-close from any open position');

  } else if (g.type === 'pedestrian'){
    bom.add('Hardware','HINGE-SC','Self-closing hinge set', 1, 'set', 'Pedestrian gates');

  } else if (g.type === 'single' || g.type === 'double'){
    if (P.temp){ bom.add('Hardware','TEMP-CLAMP','Panel coupler clamp', 2*n, 'ea', 'Gate hinge clamps'); }
    else bom.add('Hardware','HINGE-HD','Heavy-duty adjustable hinge', 2*n, 'ea', '2 per leaf');
    if (g.type === 'double') bom.add('Hardware','GATE-STOP','Centre gate stop', 1, 'ea', 'Double gates');
    if (!auto && g.type === 'double') bom.add('Hardware','DROPBOLT','Drop bolt', 1, 'ea', 'Double gates');
  } else if (g.type === 'bifold'){
    bom.add('Hardware','HINGE-HD','Heavy-duty adjustable hinge', 2*n, 'ea', '2 per panel (post and fold hinges)');
    bom.add('Hardware','BIFOLD-GUIDE','Bi-fold top guide / pivot set', 2, 'set', '1 per leaf pair');
    bom.add('Hardware','GATE-STOP','Centre gate stop', 1, 'ea');
  } else if (g.type === 'sliding'){
    const track = Math.ceil((2*g.width + rules.slidingOverlap)/1000 - 1e-9);
    bom.add('Hardware','TRACK-V','V-track ground rail', track, 'm', 'Opening × 2 + overlap');
    bom.add('Hardware','WHEEL-V','V-groove gate wheel', 2, 'ea', '2 per sliding leaf');
    bom.add('Hardware','GUIDE-ROLL','Guide roller set', 1, 'set', '1 per sliding gate');
    bom.add('Hardware','CATCH-SLIDE','Sliding gate catch / receiver', 1, 'ea');
    bom.add('Hardware','TRACK-STOP','Track end stop', 2, 'ea');
    bom.add('Concrete & footings','TRACK-FOOT','Track footing (concrete strip)', track, 'm', 'Full track length');
  } else if (g.type === 'cantilever'){
    bom.add('Gates','CANT-BEAM','Cantilever bottom track beam', Math.ceil(leafW/1000 - 1e-9), 'm', 'Full leaf length incl. counterbalance tail');
    bom.add('Hardware','CANT-ROLLER','Cantilever roller carriage', 2, 'ea', '2 per gate');
    bom.add('Hardware','CANT-GUIDE','Top guide roller', 1, 'set');
    bom.add('Hardware','CANT-ENDWHEEL','End wheel and catcher', 1, 'set');
    bom.add('Concrete & footings','CANT-FOOT','Roller carriage footing', 1, 'ea', 'Engineered to gate weight');
  }

  // ---- lock (manual gates; pool gates always get one)
  if (LOCKABLE(g.type) && (!auto || P.pool)){
    const L = LOCKS[g.lock] || LOCKS.locklatch;
    bom.add('Hardware', L.code, L.label, 1, 'ea', `Release ${LOCK_H} mm above ground level (RJL standard)` + (P.pool ? '; self-latching, opens away from the pool' : ''));
  }
  // ---- automation and access
  if (auto){
    if (g.type === 'pedestrian'){
      bom.add('Automation & access','OP-MAGNUS','Lockinox Magnus pedestrian gate operator', 1, 'ea', 'RJL standard for internal pedestrian gates'); BEAMS(1);
    } else if (SLIDES(g.type)){
      bom.add('Automation & access','OP-SLIDE','Sliding gate operator, sized to gate weight', 1, 'ea', 'Roger, FAAC, Beninca, Key or Alpha to suit');
      bom.add('Automation & access','RACK','Gear rack', Math.ceil(leafW/1000 - 1e-9), 'm', 'Full leaf length'); BEAMS(2);
    } else if (g.type === 'bifold'){
      bom.add('Automation & access','OP-BIFOLD','Bi-fold gate operator', 2, 'ea', '1 per leaf pair'); BEAMS(2);
      bom.add('Automation & access','SAFETY-EDGE','Safety edge on leading panel', 2, 'ea', 'Final count to site risk assessment');
    } else {
      bom.add('Automation & access','OP-SMARTY7','Roger Technology Smarty-7 swing operator', n, 'ea', '1 per leaf, rated to 700 kg per leaf'); BEAMS(2);
    }
    bom.add('Labour','LAB-AUTO','Install and commission gate automation', 1, 'ea');
  }
  if (g.access !== 'none'){
    bom.add('Automation & access', ACCESS[g.access].code, ACCESS[g.access].label, 1, 'ea');
    if (!auto) bom.add('Automation & access','MAGLOCK','Electric / magnetic gate lock', 1, 'ea', 'Needed for access control on a manual gate');
  }
  if (VEHICLE(g.type)) laneAccessories(run, g, bom, auto);
  if (P.topping && run.electric){
    bom.add('Automation & access','EF-GATECONTACT','Electric fence gate contact', 1, 'ea', '1 per gate in an electrified run');
    bom.add('Hardware','EF-UGCABLE','Under-gate cable (live and earth)', 2*(g.width + 2000)/1000, 'm', '2 cores × (opening + 2 m)');
  }
  bom.add('Labour',`LAB-GATE-${g.type}`,`Install ${TYPE.toLowerCase()}`, 1, 'ea');
}

/* Spikes, traffic lights, beacon and photocell posts for a vehicle lane. */
function laneAccessories(run, g, bom, auto){
  const mL = Math.ceil(g.width/1000 - 1e-9);
  if (g.spikes === 'surface'){
    bom.add('Automation & access','SPIKE-TT','Tiger Teeth one-way tyre spikes, surface mounted', mL, 'm', 'Full lane width; yellow chequer-plate ramp');
    bom.add('Hardware','SPIKE-ANCHOR','Spike anchor bolt (chemical)', mL*6, 'ea', '6 per metre (estimate)');
    bom.add('Automation & access','SPIKE-SIGN','Warning sign: one-way spikes, severe tyre damage', 2, 'ea', 'Both approaches');
    bom.add('Labour','LAB-SPIKE','Install surface tyre spikes', mL, 'm');
  }
  if (g.spikes === 'auto'){
    bom.add('Automation & access','SPIKE-AUTO','Automated in-ground tyre spike unit', mL, 'm', 'Full lane width; synchronised with the gate');
    bom.add('Automation & access','SPIKE-CTRL','Spike control and gate interlock', 1, 'ea', 'Spikes lower only when the gate is open');
    bom.add('Concrete & footings','SPIKE-PIT','Spike pit, drainage and concrete surround', mL, 'm');
    bom.add('Automation & access','SPIKE-SIGN','Warning sign: tyre spikes, severe tyre damage', 2, 'ea', 'Both approaches');
    bom.add('Labour','LAB-SPIKE-AUTO','Install and commission automated spikes', mL, 'm');
  }
  const tl = g.tlights|0;
  if (tl){
    bom.add('Automation & access','TL-RG','Red / green LED traffic light (2-aspect)', tl, 'ea', tl > 1 ? 'Both sides' : 'Approach side');
    if (g.type === 'boom' || g.type === 'bollards') bom.add('Posts','TL-POLE','Traffic light pole, 2.4 m, base-plated', tl, 'ea', 'No gate post to mount on');
    else bom.add('Hardware','TL-BRKT','Traffic light post bracket', tl, 'ea', 'Mounted on the gate post');
    bom.add('Automation & access','TL-RELAY','Traffic light relay interface', 1, 'ea', 'Green only when the lane is fully open');
  }
  if (auto && g.beacon !== false) bom.add('Automation & access','BEACON-AMBER','Amber flashing beacon (LED)', 1, 'ea', 'Flashes while the gate moves');
  if (auto && (g.type === 'boom' || g.type === 'bollards')) bom.add('Posts','BEAM-POST','Photocell post (stainless, 500 mm)', 4, 'ea', '2 pairs of beams, posts both sides');
  if (auto && (g.type === 'bollards' || g.type === 'boom')) bom.add('Automation & access','BEAMS','Photo-electric safety beams (pair)', 2, 'pair', 'Final count to site risk assessment');
}
function turnstileBom(bom){
  const t = state.turnstiles; if (!(t.count > 0)) return;
  bom.add('Turnstiles',`TURN-FH-${t.type}`,`Full-height turnstile, ${t.type} rotor`, t.count, 'ea');
  bom.add('Turnstiles','TURN-SLAB','Concrete pad for turnstile', t.count, 'ea', 'Size to manufacturer footprint');
  if (t.access !== 'none') bom.add('Automation & access', ACCESS[t.access].code, ACCESS[t.access].label, t.count, 'ea');
  bom.add('Labour','LAB-TURN','Install and commission turnstile', t.count, 'ea');
}

/* ===================================================================== COMPUTE */
let LAYOUTS = [], JOINS = [], BOM = null;
const isStrong = n => n.role !== 'end' && n.role !== 'line' && n.role !== 'corner';
function compute(){
  state.runs.forEach(r => { if (PRODUCTS[r.product].derivedHeight) r.height = palingHeight(r); });
  LAYOUTS = state.runs.map(r => layoutRun(r, state.rules));
  JOINS = state.runs.map(() => ({skipFirst:false, skipLast:false}));
  // Shared post where a run continues from the previous one: keep the stronger post (gate beats fence).
  state.runs.forEach((r,i) => {
    if (i === 0 || !r.joinPrev) return;
    const lay = LAYOUTS[i], prev = LAYOUTS[i-1];
    if (lay.errs.length || prev.errs.length || !lay.seq.length || !prev.seq.length) return;
    const first = lay.seq[0], last = prev.seq[prev.seq.length-1];
    if (isStrong(first) && !isStrong(last)) JOINS[i-1].skipLast = true;
    else { JOINS[i].skipFirst = true; if (!isStrong(last)) last.role = (r.turn % 360) ? 'corner' : 'line'; }
  });
  BOM = new Bom(); ELEC = {len:0};
  state.runs.forEach((r,i) => { const lay = LAYOUTS[i]; if (lay.errs.length) return; runBom(r, lay, JOINS[i], BOM, state.rules); gateBom(r, lay, BOM, state.rules); });
  turnstileBom(BOM);
  electricJobBom(BOM, state.rules);
  BOM.finish(state.rules.kerf);
}
function totals(){
  let mat = 0, lab = 0, unpriced = 0;
  for (const l of BOM.list){
    const r = +state.rates[l.code] || 0; if (!r) unpriced++;
    if (l.cat === 'Labour') lab += r*l.qty; else mat += r*l.qty;
  }
  const cost = mat + lab, m = clamp(+state.pricing.margin || 0, 0, 90)/100;
  const sell = cost/(1 - m), gst = state.pricing.gst ? sell*0.1 : 0;
  const pm = (+state.pricing.pmVisits || 0) * (+state.pricing.pmRate || 0);
  return {mat, lab, cost, sell, profit:sell - cost, gst, total:sell + gst, unpriced, pm};
}

/* ===================================================================== UI */
function icon(k){
  const posts = '<rect x="2" y="2" width="3" height="26" fill="currentColor"/><rect x="43" y="2" width="3" height="26" fill="currentColor"/>';
  let body = '';
  if (k === 'colorbond'){ body = '<rect x="5" y="5" width="38" height="20" fill="none" stroke="currentColor" stroke-width="1.6"/>'; for (let x=9;x<43;x+=4) body += `<line x1="${x}" y1="6" x2="${x}" y2="24" stroke="currentColor" stroke-width="1"/>`; }
  if (k === 'hslat'){ for (let y=5;y<27;y+=3.2) body += `<rect x="5" y="${y}" width="38" height="2.2" fill="currentColor"/>`; }
  if (k === 'vslat'){ for (let x=7;x<42;x+=4.2) body += `<rect x="${x}" y="4" width="2.6" height="22" fill="currentColor"/>`; body += '<rect x="5" y="8" width="38" height="1.4" fill="currentColor"/><rect x="5" y="21" width="38" height="1.4" fill="currentColor"/>'; }
  if (k === 'chain'){ body = '<rect x="5" y="3" width="38" height="2" fill="currentColor"/>'; for (let x=-20;x<48;x+=6){ body += `<line x1="${x}" y1="5" x2="${x+22}" y2="27" stroke="currentColor" stroke-width=".9"/><line x1="${x+22}" y1="5" x2="${x}" y2="27" stroke="currentColor" stroke-width=".9"/>`; } body = `<svg x="5" y="0" width="38" height="30" viewBox="5 0 38 30">${body}</svg>`; }
  if (k === 'mesh358'){ for (let x=6;x<43;x+=2.2) body += `<line x1="${x}" y1="3" x2="${x}" y2="27" stroke="currentColor" stroke-width=".7"/>`; for (let y=4;y<28;y+=6) body += `<line x1="5" y1="${y}" x2="43" y2="${y}" stroke="currentColor" stroke-width="1"/>`; }
  if (k === 'tubular'){ body = '<rect x="5" y="6" width="38" height="2" fill="currentColor"/><rect x="5" y="23" width="38" height="2" fill="currentColor"/>'; for (let x=8;x<43;x+=4) body += `<rect x="${x}" y="3" width="1.6" height="25" fill="currentColor"/>`; }
  if (k === 'paling'){ for (let x=5;x<43;x+=4.75) body += `<rect x="${x}" y="4" width="4.2" height="24" fill="currentColor" opacity=".85"/>`; }
  if (k === 'picket'){ for (let x=6;x<42;x+=5) body += `<polygon points="${x},10 ${x+1.5},6 ${x+3},10 ${x+3},26 ${x},26" fill="currentColor"/>`; body += '<rect x="5" y="12" width="38" height="1.4" fill="currentColor"/><rect x="5" y="22" width="38" height="1.4" fill="currentColor"/>'; }
  if (k === 'vblade'){ for (let x=6;x<43;x+=3.4) body += `<polygon points="${x},5 ${x+2.6},4 ${x+2.6},26 ${x},27" fill="currentColor"/>`; body += '<rect x="5" y="3" width="38" height="1.4" fill="currentColor"/><rect x="5" y="27" width="38" height="1.4" fill="currentColor"/>'; }
  if (k === 'sbatten'){ for (let x=6;x<42;x+=5.4) body += `<rect x="${x}" y="3" width="3.8" height="25" fill="currentColor"/>`; body += '<rect x="5" y="8" width="38" height="1.2" fill="currentColor" opacity=".6"/><rect x="5" y="22" width="38" height="1.2" fill="currentColor" opacity=".6"/>'; }
  if (k === 'poolalu'){ body = '<rect x="5" y="6" width="38" height="2" fill="currentColor"/><rect x="5" y="24" width="38" height="2" fill="currentColor"/>'; for (let x=8;x<43;x+=3.5) body += `<rect x="${x}" y="6" width="1.1" height="20" fill="currentColor"/>`; }
  if (k === 'glass'){ return `<svg viewBox="0 0 48 30" aria-hidden="true"><rect x="3" y="5" width="20" height="20" fill="currentColor" opacity=".25" stroke="currentColor" stroke-width="1"/><rect x="25" y="5" width="20" height="20" fill="currentColor" opacity=".25" stroke="currentColor" stroke-width="1"/><rect x="7" y="23" width="3" height="5" fill="currentColor"/><rect x="16" y="23" width="3" height="5" fill="currentColor"/><rect x="29" y="23" width="3" height="5" fill="currentColor"/><rect x="38" y="23" width="3" height="5" fill="currentColor"/></svg>`; }
  if (k === 'mesh868'){ for (let x=6;x<43;x+=3) body += `<line x1="${x}" y1="3" x2="${x}" y2="27" stroke="currentColor" stroke-width=".8"/>`; for (let y=5;y<28;y+=7) body += `<line x1="5" y1="${y}" x2="43" y2="${y}" stroke="currentColor" stroke-width="1"/><line x1="5" y1="${y+1.6}" x2="43" y2="${y+1.6}" stroke="currentColor" stroke-width="1"/>`; }
  if (k === 'palisade'){ for (let x=6;x<42;x+=5) body += `<polygon points="${x},6 ${x+1},3 ${x+2},6 ${x+3},3 ${x+4},6 ${x+4},28 ${x},28" fill="currentColor"/>`; body += '<rect x="5" y="9" width="38" height="1.2" fill="currentColor" opacity=".6"/><rect x="5" y="23" width="38" height="1.2" fill="currentColor" opacity=".6"/>'; }
  if (k === 'garrison'){ body = '<rect x="5" y="8" width="38" height="2" fill="currentColor"/><rect x="5" y="17" width="38" height="2" fill="currentColor"/><rect x="5" y="25" width="38" height="2" fill="currentColor"/>'; for (let x=8;x<42;x+=4) body += `<rect x="${x}" y="5" width="1.6" height="23" fill="currentColor"/><polygon points="${x-.8},5 ${x+.8},1.5 ${x+2.4},5" fill="currentColor"/>`; }
  if (k === 'temp'){ return `<svg viewBox="0 0 48 30" aria-hidden="true"><rect x="3" y="3" width="20" height="21" fill="none" stroke="currentColor" stroke-width="1.6"/><rect x="25" y="3" width="20" height="21" fill="none" stroke="currentColor" stroke-width="1.6"/>${[6,10,14,18].map(x=>`<line x1="${x}" y1="4" x2="${x}" y2="23" stroke="currentColor" stroke-width=".6"/><line x1="${x+22}" y1="4" x2="${x+22}" y2="23" stroke="currentColor" stroke-width=".6"/>`).join('')}<rect x="0" y="24" width="7" height="4" fill="currentColor"/><rect x="20.5" y="24" width="7" height="4" fill="currentColor"/><rect x="41" y="24" width="7" height="4" fill="currentColor"/></svg>`; }
  return `<svg viewBox="0 0 48 30" aria-hidden="true">${posts}${body}</svg>`;
}
