      const g0 = y0 - 50;                                                     // ground line inside the bay
      const ns = run.sleepers|0, np = Math.max(1, run.plinths|0), capH = run.capping ? 60 : 0;
      let y = g0;
      for (let k=0;k<ns;k++){ B.box(mTd, cx, y + 100, z + 6, w, 196, 50); y += PAL_SLEEPER; }   // treated pine sleepers
      for (let k=0;k<np;k++){ B.box(mT, cx, y + 75, z + 10, w, 146, 25); y += PAL_PLINTH; }       // plinth board(s)
      const pTop = y1 - capH, pBot = y - 20, ph = pTop - pBot;                                    // palings sit just behind the top plinth
